CL_OLD = "margin on every side, corners parallel to the card's - like the ring around every other card.\n"
CL_NEW = 'margin on every side, corners parallel to the card\'s - like the ring around every other card.\n\n**A distinct abstain state.** When the system names no vessel - keyed on its own output,\nunknown_source, never on the case\'s family, so a wrongly named absent-source case still\nshows as the failure it is - Case Finding says so as a decision: "The system abstains" on\nan amber-rimmed surface, with a meter placing every replayed candidate\'s fit against the\ngate so it is visible that none reaches it. Its note no longer claims declining was "the\ncorrect output": the interface has no ground truth to know that.\n'
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 26 entry this appends after was not found")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 27: {len(writes)} files written, {skipped} already in place.")
